package com.counselor.repository; import com.counselor.entity.Submission; import com.counselor.enums.SubmissionStatus;
import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.data.jpa.repository.JpaRepository; import java.util.List; import java.util.Optional;
public interface SubmissionRepository extends JpaRepository<Submission,Long> { List<Submission> findByCounselorIdOrderByCreatedAtDesc(Long counselorId); Page<Submission> findByBatchId(Long batchId,Pageable pageable); List<Submission> findByBatchIdAndStatus(Long batchId,SubmissionStatus status); boolean existsByCounselorIdAndBatchId(Long counselorId,Long batchId); Optional<Submission> findByCounselorIdAndBatchId(Long counselorId,Long batchId); List<Submission> findByBatchId(Long batchId); long countByBatchIdAndStatus(Long batchId, SubmissionStatus status); }
